fn extract_tool_name(line: &str) -> Option<String> {
    // Common patterns: "Using tool: tool_name" or "tool_call: tool_name"
    let patterns = ["using tool:", "calling tool:", "tool_call:", "tool:"];
    let line_lower = line.to_lowercase();

    for pattern in patterns.iter() {
        if let Some(pos) = line_lower.find(pattern) {
            let rest = &line_lower[pos + pattern.len()..];
            let tool = rest.split_whitespace().next()?.trim_matches(':').to_string();
            if !tool.is_empty() {
                return Some(tool);
            }
        }
    }
    None
}

fn parse_coordination_line(line: &str) -> Option<CoordinationMessage> {
    // Format: [2024-02-03T18:52:34Z] FROM → TO: content
    let re = regex::Regex::new(r"^\[([^\]]+)\] ([^ ]+) → ([^:]+): (.*)$").ok()?;
    let caps = re.captures(line)?;

    let timestamp = DateTime::parse_from_rfc3339(&caps[1])
        .ok()?
        .with_timezone(&Utc);

    Some(CoordinationMessage {
        id: uuid::Uuid::new_v4().to_string(),
        timestamp,
        from: caps[2].to_string(),
        to: caps[3].to_string(),
        content: caps[4].to_string(),
        message_type: crate::coordination::MessageType::Task,
    })
}

pub(crate) fn normalize_preview_input(input: &str) -> String {
    let trimmed = input.trim();
    if trimmed.is_empty() || has_explicit_scheme(trimmed) {
        return trimmed.to_string();
    }

    let host = schemeless_host(trimmed);
    if host.is_empty() {
        // Path-only input (`/relative/path`, `?q=1`) has no authority to attach a
        // scheme to. It is returned unchanged so `Url::parse` rejects it. Prepending
        // anyway would produce `https:///relative/path`, and the WHATWG
        // "special authority ignore slashes" rule collapses the extra slash and
        // promotes `relative` to the HOST - silently inventing an origin the
        // operator never typed.
        return trimmed.to_string();
    }

    let scheme = if is_localhostish_host(host) {
        "http"
    } else {
        "https"
    };

    format!("{scheme}://{trimmed}")
}

pub fn context_node_is_stale(
    node: &WorkNode,
    fingerprints: &[KnowledgeSourceFingerprint],
) -> bool {
    let Some(expansion) = node.expansion.as_ref() else {
        return false;
    };
    if expansion.template != DERIVED_CONTEXT_TEMPLATE {
        return false;
    }
    let Some(fingerprint_ref) = expansion.parameters.get("fingerprint_ref") else {
        return true;
    };
    let Some(recorded_hash) = expansion.parameters.get("source_hash") else {
        return true;
    };
    fingerprints
        .iter()
        .find(|fingerprint| fingerprint_ref == &fingerprint.source_ref)
        .map_or(true, |fingerprint| {
            fingerprint.content_hash != *recorded_hash
        })
}

fn parse_submit_gap_override(value: Option<&std::ffi::OsStr>) -> SubmitGapOverride {
    let Some(value) = value else {
        return SubmitGapOverride::Unset;
    };
    let Some(milliseconds) = value.to_str() else {
        return SubmitGapOverride::Invalid(SubmitGapInvalidReason::NonUnicode);
    };

    match milliseconds.trim().parse::<u64>() {
        Ok(requested_ms) if requested_ms <= MAX_PTY_SUBMIT_GAP_OVERRIDE_MS => {
            SubmitGapOverride::Valid(Duration::from_millis(requested_ms))
        }
        Ok(requested_ms) => SubmitGapOverride::OverLimit { requested_ms },
        Err(error)
            if matches!(
                error.kind(),
                &std::num::IntErrorKind::PosOverflow | &std::num::IntErrorKind::NegOverflow
            ) =>
        {
            SubmitGapOverride::Invalid(SubmitGapInvalidReason::Overflow)
        }
        Err(_) => SubmitGapOverride::Invalid(SubmitGapInvalidReason::NotUnsignedInteger),
    }
}

pub fn record_step_finished(
    &self,
    run_id: &str,
    step_id: &str,
    status: StepStatus,
) -> Result<(), StorageError> {
    let finished_at = Utc::now().to_rfc3339();
    self.db.with_conn(|conn| {
        conn.execute(
            "UPDATE run_journal SET status=?1, finished_at=?2 WHERE run_id=?3 AND step_id=?4",
            params![status.as_tag(), finished_at, run_id, step_id],
        )?;
        Ok(())
    })?;
    Ok(())
}

pub fn get_row(&self, id: &str) -> Result<Option<QueueRow>, StorageError> {
    self.db.with_conn(|conn| {
        let row = conn
            .query_row(
                "SELECT queue.id, queue.task_id, queue.session_id, queue.worker_id,
                        queue.role_type, queue.cli, queue.status, queue.payload,
                        queue.attempts, queue.continuation_count, queue.no_progress_count,
                        queue.last_status, queue.heartbeat_at, queue.assignment_id,
                        queue.created_at, queue.updated_at, block.reason
                 FROM agent_run_queue AS queue
                 LEFT JOIN agent_run_queue_blocks AS block ON block.queue_id = queue.id
                 WHERE queue.id = ?1",
                params![id],
                row_to_queue_row,
            )
            .optional()?;
        Ok(row)
    })
}

fn journal_node(id: &str, entry: &RunJournalEntry) -> WorkNode {
    WorkNode::new(
        id,
        NodeKind::Context,
        format!("Journaled {:?} step", entry.kind),
        NodeContract {
            inputs: entry.detail.clone().into_iter().collect(),
            outputs: vec![format!("{id}:status={}", entry.status.as_tag())],
            acceptance: vec!["step exists in the run journal".to_string()],
        },
        BindingRef::Role("run_journal".to_string()),
        match entry.status {
            StepStatus::Started => NodeStatus::Running,
            StepStatus::Completed | StepStatus::Skipped => NodeStatus::Completed,
            StepStatus::Failed => NodeStatus::Failed,
            StepStatus::Interrupted | StepStatus::Unknown => NodeStatus::Blocked,
        },
    )
}

pub fn spawn(
    self: &Arc<Self>,
    command: &str,
    args: &[String],
    cwd: &Path,
    env: &[(String, String)],
    on_message: Arc<dyn Fn(Value) + Send + Sync>,
) -> Result<(), String> {
    let inherited: Vec<_> = std::env::vars_os().collect();
    require_subscription_env(inherited.clone())?;
    require_subscription_env(env.iter().map(|(k, v)| (k.into(), v.into())))?;
    let mut cmd = Command::new(command);
    cmd.args(args)
        .current_dir(cwd)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    for (name, _) in &inherited {
        if name
            .to_string_lossy()
            .to_ascii_uppercase()
            .starts_with("HIVE_")
        {
            cmd.env_remove(name);
        }
    }
    remove_parent_env(&mut cmd, inherited);
    cmd.envs(env.iter().map(|(k, v)| (k, v)));
    remove_parent_env(&mut cmd, env.iter().map(|(k, v)| (k.into(), v.into())));
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x0800_0000 | 0x0000_0004);
    }
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        cmd.process_group(0);
    }
    let mut slot = self.child.lock();
    if self.cancelled.load(Ordering::Acquire) {
        return Err("Claude startup cancelled".into());
    }
    let mut child = cmd.spawn().map_err(|e| {
        format!("Cannot start Claude stream-json: {e}. Select PTY in launch settings.")
    })?;
    match crate::transport::process::ProcessTree::attach(&child) {
        Ok(tree) => *self.tree.lock() = Some(tree),
        Err(error) => {
            if let Err(cleanup) = child.kill().and_then(|_| child.wait().map(|_| ())) {
                *slot = Some(child);
                return Err(format!("{error}; suspended-root cleanup failed: {cleanup}"));
            }
            return Err(error);
        }
    }
    let stdout = child.stdout.take().ok_or("Claude stdout unavailable")?;
    let stderr = child.stderr.take().ok_or("Claude stderr unavailable")?;
    let mut pipe = child.stdin.take().ok_or("Claude stdin unavailable")?;
    let (tx, rx) = mpsc::sync_channel::<Vec<u8>>(16);
    *self.stdin.lock() = Some(tx);
    *slot = Some(child);
    self.alive.store(true, Ordering::Release);
    drop(slot);
    let monitor = self.clone();
    std::thread::Builder::new()
        .name("claude-liveness".into())
        .spawn(move || {
            while monitor.alive.load(Ordering::Acquire) {
                let exited = monitor
                    .child
                    .lock()
                    .as_mut()
                    .is_none_or(|child| crate::transport::process::child_has_exited(child).unwrap_or(false));
                if exited {
                    monitor.alive.store(false, Ordering::Release);
                    monitor.fail_pending("Claude stream-json exited; select PTY to restart");
                    if let Some(tree) = monitor.tree.lock().as_ref() {
                        let _ = tree.terminate();
                    }
                    break;
                }
                std::thread::sleep(Duration::from_millis(100));
            }
        })
        .map_err(|e| e.to_string())?;
    let writer = self.clone();
    std::thread::Builder::new()
        .name("claude-writer".into())
        .spawn(move || {
            for bytes in rx {
                if pipe.write_all(&bytes).and_then(|_| pipe.flush()).is_err() {
                    writer.alive.store(false, Ordering::Release);
                    writer.fail_pending("Claude input closed; select PTY");
                    let _ = writer.stop();
                    break;
                }
            }
        })
        .map_err(|e| e.to_string())?;
    std::thread::Builder::new()
        .name("claude-stderr".into())
        .spawn(move || {
            let _ = std::io::copy(&mut BufReader::new(stderr), &mut std::io::sink());
        })
        .map_err(|e| e.to_string())?;
    let client = self.clone();
    std::thread::Builder::new().name("claude-jsonl".into()).spawn(move || {
        let mut reader = BufReader::new(stdout);
        loop {
            let mut bytes = Vec::new();
            match reader.by_ref().take(MAX_FRAME_BYTES + 1).read_until(b'\n', &mut bytes) {
                Ok(0) | Err(_) => break,
                _ if bytes.len() as u64 > MAX_FRAME_BYTES => break,
                _ => {}
            }
            let Ok(message) = serde_json::from_slice::<Value>(&bytes) else { break; };
            if message["type"] == "control_response" {
                let response = &message["response"];
                if let Some(id) = response["request_id"].as_str() {
                    if let Some(tx) = client.pending.lock().remove(id) {
                        let reply = if response["subtype"] == "success" {
                            Ok(response["response"].clone())
                        } else { Err("Claude rejected a control request; select PTY for this configuration".into()) };
                        let _ = tx.send(reply);
                    }
                }
            } else { on_message(message); }
        }
        client.alive.store(false, Ordering::Release);
        client.fail_pending("Claude exited or sent invalid/oversized JSON. Select PTY to retry.");
        let _ = client.stop();
    }).map_err(|e| e.to_string())?;
    Ok(())
}

pub fn discard_worker_slot(&self, session_id: &str, worker_id: &str) -> Result<u8, String> {
    let (session, worker_index, worker_commit_sha, worker_base_commit_sha) = {
        let sessions = self.sessions.read();
        let session = sessions
            .get(session_id)
            .cloned()
            .ok_or_else(|| format!("Session not found: {}", session_id))?;
        let agent = session
            .agents
            .iter()
            .find(|a| a.id == worker_id && matches!(a.role, AgentRole::Worker { .. }))
            .ok_or_else(|| {
                format!(
                    "Worker {} is not a rostered worker of session {}",
                    worker_id, session_id
                )
            })?;
        let index = match agent.role {
            AgentRole::Worker { index, .. } => index,
            _ => unreachable!("filtered to Worker above"),
        };
        (
            session.clone(),
            index,
            agent.commit_sha.clone(),
            agent.base_commit_sha.clone(),
        )
    };

    if worker_commit_sha.is_some() {
        return Err(format!(
            "Worker {} has a recorded completion commit; refusing to discard a slot \
             that produced work",
            worker_id
        ));
    }

    let uses_shared_workspace = !session.no_git
        && matches!(&session.session_type, SessionType::Hive { .. })
        && session.execution_policy.workspace_strategy == WorkspaceStrategy::SharedCell;
    let creates_worker_worktree = !session.no_git && !uses_shared_workspace;
    let worker_cell_name = format!("worker-{worker_index}");

    // Mirror add_worker's artifact layout exactly: task file (strategy-dependent),
    // prompt file under the worker cwd, and the per-worker worktree + branch.
    let task_file_path =
        Self::task_file_path_for_session_worker(&session, worker_index as usize)?;
    let worker_cwd = if session.no_git {
        session.project_path.clone()
    } else if uses_shared_workspace {
        session
            .worktree_path
            .as_ref()
            .map(PathBuf::from)
            .unwrap_or_else(|| session.project_path.clone())
    } else {
        session
            .project_path
            .join(".hive-manager")
            .join("worktrees")
            .join(session_id)
            .join(&worker_cell_name)
    };
    let prompt_file = worker_cwd
        .join(".hive-manager")
        .join("prompts")
        .join(format!("worker-{}-prompt.md", worker_index));

    // For isolated git lanes, prove the lane is empty before destroying it. A worker
    // killed mid-run has commits past its base or a dirty worktree; a phantom that
    // never executed an instruction has neither.
    if creates_worker_worktree && worker_cwd.exists() {
        match current_head(&worker_cwd) {
            Ok(tip) => match &worker_base_commit_sha {
                Some(base) if *base == tip => {}
                Some(base) => {
                    return Err(format!(
                        "Worker {} branch has advanced past its base ({} -> {}); \
                         refusing to discard a slot that produced work",
                        worker_id, base, tip
                    ));
                }
                None => {
                    return Err(format!(
                        "Worker {} has no recorded base commit to compare against; \
                         refusing to discard — clean up the worktree manually if the \
                         lane is truly empty",
                        worker_id
                    ));
                }
            },
            // No resolvable HEAD (worktree half-created) — nothing to preserve.
            Err(_) => {}
        }

        if Self::worktree_has_local_changes(&worker_cwd) {
            return Err(format!(
                "Worker {} worktree has uncommitted changes; refusing to discard a \
                 slot that produced work",
                worker_id
            ));
        }
    }

    Self::rollback_worker_launch_artifacts(
        &session.project_path,
        session_id,
        &worker_cell_name,
        &task_file_path,
        Some(&prompt_file),
        creates_worker_worktree,
    );

    {
        let mut sessions = self.sessions.write();
        if let Some(session) = sessions.get_mut(session_id) {
            session.agents.retain(|a| a.id != worker_id);
        }
    }
    self.update_session_storage(session_id);
    self.emit_session_update(session_id);

    tracing::info!(
        session = %session_id,
        worker = %worker_id,
        index = worker_index,
        "discarded dead worker slot; index is reusable"
    );
    Ok(worker_index)
}

pub fn launch_evaluator(
    &self,
    session_id: &str,
    mut config: AgentConfig,
    smoke_test: bool,
) -> Result<AgentInfo, String> {
    crate::instance::refuse("agent launch")?;
    let session = self
        .get_session(session_id)
        .ok_or_else(|| format!("Session not found: {}", session_id))?;

    let evaluator_id = format!("{}-evaluator", session_id);
    if let Some(existing) = session.agents.iter().find(|agent| agent.id == evaluator_id) {
        let evaluator_alive = self.pty_manager.read().is_alive(&evaluator_id);
        if evaluator_alive {
            return Ok(existing.clone());
        }
        tracing::info!(
            session_id = %session_id,
            evaluator_id = %evaluator_id,
            "Respawning stale evaluator after PTY exit"
        );
    }

    let uses_session_default_cli = config.cli.trim().is_empty();
    if uses_session_default_cli {
        config.cli = session.default_cli.clone();
    }
    let uses_session_cli = uses_session_default_cli || config.cli.trim() == session.default_cli;
    if config.model.is_none() {
        config.model = if uses_session_cli {
            session.default_model.clone()
        } else {
            CliRegistry::default_model(&config.cli)
                .map(ToString::to_string)
                .or_else(|| session.default_model.clone())
        };
    }
    if config.label.is_none() {
        config.label = Some("Evaluator".to_string());
    }

    // #175(a): capture the state we are transitioning AWAY from, so the tail
    // can restore it. Restoring the captured state rather than a hardcoded
    // `Running` also fixes a latent iteration-loss bug: the tail used to read
    // `qa_in_progress_state(&current.state)` AFTER this block had already
    // written `SpawningEvaluator`, so a respawn from `QaFailed { iteration: 2 }`
    // fell to the catch-all arm and reset the counter to `None`, defeating the
    // max-retries ceiling.
    let (previous_state, spawning_changes) =
        {
            let mut sessions = self.sessions.write();
            if let Some(current) = sessions.get_mut(session_id) {
                let previous_state = current.state.clone();
                current.agents.retain(|agent| agent.id != evaluator_id);
                (
                    Some(previous_state),
                    Some(self.set_session_state_with_events(
                        current,
                        SessionState::SpawningEvaluator,
                    )),
                )
            } else {
                (None, None)
            }
        };
    self.emit_session_update(session_id);
    self.update_session_storage(session_id);
    if let Some(changes) = spawning_changes {
        self.emit_cell_status_changes(session_id, changes);
    }

    Self::write_tool_files(
        &session.project_path,
        session_id,
        Self::session_principal_cli(&session),
        &session.default_cli,
    )?;

    let worker_count = match session.session_type {
        SessionType::Hive { worker_count } => worker_count,
        _ => 0,
    };
    let execution_workspace = Self::execution_workspace(&session);
    let evaluator_prompt = Self::build_evaluator_prompt(
        session_id,
        &config,
        &session.qa_workers,
        worker_count,
        &execution_workspace,
        smoke_test,
        &session.project_path,
    );
    let prompt_file = Self::write_prompt_file(
        &session.project_path,
        session_id,
        "evaluator-prompt.md",
        &evaluator_prompt,
    )?;

    let (cmd, mut args) = Self::build_command(&config);
    Self::add_prompt_to_args(&cmd, &mut args, &prompt_file.to_string_lossy());

    // #125: record the evaluator-spawn write-step as Started before the PTY spawn.
    let evaluator_journal_step = self.journal_step_started(
        session_id,
        crate::domain::run_journal::StepKind::EvaluatorSpawn,
        0,
        Some("evaluator"),
    );

    let cwd = session.project_path.to_str().unwrap_or(".");
    let transcript_spawned_at = Some(Utc::now());
    {
        let pty_manager = self.pty_manager.read();
        pty_manager
            .create_session(
                evaluator_id.clone(),
                AgentRole::Evaluator,
                &cmd,
                &args.iter().map(|s| s.as_str()).collect::<Vec<_>>(),
                Some(cwd),
                120,
                30,
            )
            .map_err(|e| {
                if let Some(step_id) = evaluator_journal_step.as_deref() {
                    self.journal_step_finished(
                        session_id,
                        step_id,
                        crate::domain::run_journal::StepStatus::Failed,
                    );
                }
                format!("Failed to spawn Evaluator: {}", e)
            })?;
    }

    let agent_info = AgentInfo {
        work_state: None,
        transcript_spawned_at,
        provider_session_id: None,
        transcript_session_id: Self::transcript_key(&cmd, &args),
        id: evaluator_id,
        role: AgentRole::Evaluator,
        status: AgentStatus::Running,
        config,
        parent_id: None,
        role_definition_id: None,
        role_definition_version: None,
        commit_sha: None,
        base_commit_sha: None,
    };

    // #175(a): spawning an Evaluator does NOT open a QA window. It used to
    // transition straight to QaInProgress and arm the 300s QA timer, and
    // because this runs at SESSION LAUNCH, every evaluator-backed session ran
    // a live QA clock from the moment it started. Any session whose first
    // milestone took longer than the timeout was deterministically poisoned
    // to QaInconclusive with a spurious BLOCKED/timeout verdict for work that
    // had never been submitted for review.
    //
    // The clock is now armed only by `begin_qa_window`, at milestone handoff.
    let qa_changes = {
        let mut sessions = self.sessions.write();
        let current = sessions
            .get_mut(session_id)
            .ok_or_else(|| format!("Session not found: {}", session_id))?;
        current.agents.push(agent_info.clone());
        self.emit_agent_launched(current, &agent_info);
        // Restore the pre-spawn state, but only if we are still the ones
        // holding SpawningEvaluator: the sessions lock is released across the
        // PTY spawn and two file writes above, so an unguarded restore could
        // silently revert a concurrent Failed/Closing/Closed transition.
        match (&current.state, previous_state) {
            (SessionState::SpawningEvaluator, Some(previous)) => {
                Some(self.set_session_state_with_events(current, previous))
            }
            _ => None,
        }
    };

    self.emit_session_update(session_id);
    self.update_session_storage(session_id);
    if let Some(changes) = qa_changes {
        self.emit_cell_status_changes(session_id, changes);
    }
    // The peer watcher must still exist — without it the milestone handoff is
    // never observed.
    self.ensure_task_watcher(session_id, &session.project_path);

    // #125: evaluator spawned successfully — mark the write-step Completed.
    if let Some(step_id) = evaluator_journal_step.as_deref() {
        self.journal_step_finished(
            session_id,
            step_id,
            crate::domain::run_journal::StepStatus::Completed,
        );
    }

    Ok(agent_info)
}

fn on_milestone_ready_with_mtime(
    &self,
    session_id: &str,
    file_mtime: Option<DateTime<Utc>>,
) -> Result<(), String> {
    let (maybe_evaluator, config, reentering, ceiling_exceeded) = {
        let sessions = self.sessions.read();
        let session = sessions
            .get(session_id)
            .ok_or_else(|| format!("Session not found: {}", session_id))?;

        let reentering = matches!(&session.state, SessionState::QaInconclusive);
        if reentering {
            let fresh = match file_mtime {
                None => true, // A live HTTP POST is fresh by construction.
                Some(modified) => session
                    .qa_inconclusive_at
                    .as_ref()
                    .map(|checkpoint| modified > checkpoint.at)
                    .unwrap_or(false),
            };
            if !fresh {
                let reason = "milestone-ready file is not newer than the inconclusive QA verdict";
                tracing::warn!(session_id, "Ignoring stale milestone-ready file");
                if let Some(storage) = self.storage.as_ref() {
                    let msg = crate::coordination::CoordinationMessage::system(
                        "OPERATOR",
                        reason,
                    );
                    let _ = storage.append_coordination_log(session_id, &msg);
                }
                self.emit_qa_inconclusive_event(session_id, reason);
                return Ok(());
            }
        }

        if matches!(
            &session.state,
            SessionState::PrinceRemediation
                | SessionState::QaPassed
                | SessionState::QaMaxRetriesExceeded
        ) {
            tracing::debug!(
                session_id = %session_id,
                state = ?session.state,
                "Ignoring duplicate milestone-ready signal for gated QA session"
            );
            return Ok(());
        }

        let maybe_evaluator = session
            .agents
            .iter()
            .find(|agent| matches!(agent.role, AgentRole::Evaluator))
            .cloned();

        let config = maybe_evaluator
            .as_ref()
            .map(|agent| agent.config.clone())
            .unwrap_or_else(|| AgentConfig {
                cli: session.default_cli.clone(),
                model: session.default_model.clone(),
                flags: vec![],
                label: Some("Evaluator".to_string()),
                name: None,
                description: None,
                role: None,
                initial_prompt: None,
            });

        let next_iteration = session
            .qa_inconclusive_at
            .as_ref()
            .and_then(|checkpoint| checkpoint.prior_iteration)
            .unwrap_or(0) as u16 + 1;
        let ceiling_exceeded = reentering && next_iteration > session.max_qa_iterations as u16;
        (maybe_evaluator, config, reentering, ceiling_exceeded)
    };

    if ceiling_exceeded {
        let changes = {
            let mut sessions = self.sessions.write();
            let session = sessions
                .get_mut(session_id)
                .ok_or_else(|| format!("Session not found: {}", session_id))?;
            session.auth_strategy = AuthStrategy::None;
            self.set_session_state_with_events(session, SessionState::QaMaxRetriesExceeded)
        };
        self.update_session_storage(session_id);
        self.emit_session_update(session_id);
        self.emit_cell_status_changes(session_id, changes);
        return Ok(());
    }

    let evaluator_alive = maybe_evaluator
        .as_ref()
        .map(|agent| self.pty_manager.read().is_alive(&agent.id))
        .unwrap_or(false);

    if maybe_evaluator.is_none() || !evaluator_alive {
        if !self.try_begin_evaluator_respawn(session_id) {
            tracing::debug!(
                session_id = %session_id,
                "Ignoring duplicate milestone-ready signal while evaluator respawn is already in flight"
            );
            return Ok(());
        }

        tracing::info!(
            session_id = %session_id,
            reason = if maybe_evaluator.is_some() { "dead_evaluator" } else { "missing_evaluator" },
            "Launching evaluator from milestone-ready signal"
        );
        let result = if reentering {
            self.rotate_inconclusive_verdicts(session_id)
                .and_then(|_| self.launch_evaluator(session_id, config, false))
        } else {
            self.launch_evaluator(session_id, config, false)
        };
        self.finish_evaluator_respawn(session_id);
        result?;
        // #175(a) THE TRAP: this branch used to rely on `launch_evaluator`'s
        // tail to transition and arm the clock. Now that spawning an
        // Evaluator no longer opens a QA window, this branch must open it
        // itself -- otherwise the fix for a spurious-timeout bug becomes a
        // never-times-out bug, and a real milestone would sit unreviewed
        // forever.
        self.begin_qa_window(session_id)?;
        return Ok(());
    }

    if reentering {
        self.rotate_inconclusive_verdicts(session_id)?;
    }
    self.begin_qa_window(session_id)
}

pub fn archive_completed_session(
    storage_base_dir: &Path,
    run_journal: Option<&RunJournalStore>,
    session_id: &str,
) -> Result<ArchiveCompletion, ArchiveError> {
    validate_session_id(session_id)?;
    let storage = SessionStorage::new_with_base(storage_base_dir.to_path_buf())
        .map_err(|error| ArchiveError::Storage(error.to_string()))?;
    let session_dir = storage.session_dir(session_id);
    let archive_dir = session_dir.join("archive").join("work-graphs");
    fs::create_dir_all(&archive_dir)?;

    let archive_id = archive_id_for_session(session_id);
    let target = archive_dir.join(format!("{archive_id}.json"));
    if target.exists() {
        let archive = read_archive(&target)?;
        StateManager::new(session_dir)
            .write_portable_work_graph_artifact(
                "archived",
                &archive.runtime_graph,
                Some(&archive.divergence),
            )
            .map_err(|error| ArchiveError::Storage(error.to_string()))?;
        return Ok(ArchiveCompletion {
            archive,
            path: target,
            created: false,
        });
    }

    let state = StateManager::new(session_dir.clone());
    let (plan_graph, plan_report) = match state.read_work_graph() {
        Ok(Some(graph)) => (
            Some(graph),
            source_report(
                ArchiveSourceKind::PlanGraph,
                "state/work-graph.json",
                true,
                1,
            ),
        ),
        Ok(None) => {
            let mut report = source_report(
                ArchiveSourceKind::PlanGraph,
                "state/work-graph.json",
                false,
                0,
            );
            source_omission(
                &mut report,
                WorkGraphOmissionReason::SourceUnreadable,
                "state/work-graph.json",
            );
            (None, report)
        }
        Err(error) => {
            let mut report = source_report(
                ArchiveSourceKind::PlanGraph,
                "state/work-graph.json",
                false,
                0,
            );
            source_omission(
                &mut report,
                WorkGraphOmissionReason::SourceUnreadable,
                "state/work-graph.json:invalid",
            );
            report.omissions[0].detail = format!(
                "work graph could not be read; runtime structure may be incomplete: {error}"
            );
            (None, report)
        }
    };

    let event_log_path = storage_base_dir.join(session_id).join("events.jsonl");
    let (events, event_report) = read_event_log(&event_log_path, session_id);
    let (completion_facts, completion_ledger_omission) =
        match read_node_completion_facts(&session_dir) {
            Ok(facts) => (facts, None),
            Err(error) => {
                let mut omission = WorkGraphOmission::new(
                    WorkGraphOmissionReason::SourceUnreadable,
                    1,
                    vec!["state/work-graph-completions.jsonl".to_string()],
                );
                omission.detail = format!(
                    "declared node completions could not be read and were omitted: {error}"
                );
                (Vec::new(), Some(omission))
            }
        };
    let (journal, journal_report, ledger, ledger_report) =
        read_run_sources(run_journal, session_id);
    let mutation_snapshot = mutation_log_snapshot(session_id);
    let deltas = mutation_snapshot.deltas;
    let mut mutation_report = source_report(
        ArchiveSourceKind::MutationLog,
        "memory/session-mutation-log",
        mutation_snapshot.tracked,
        deltas.len(),
    );
    if !mutation_snapshot.tracked {
        source_omission(
            &mut mutation_report,
            WorkGraphOmissionReason::ResolutionIncomplete,
            "mutation-log:not-observed-in-this-process",
        );
        mutation_report.omissions[0].detail =
            "the process did not observe a mutation boundary for this session; zero deltas cannot prove that no earlier structural mutations occurred"
                .to_string();
    } else if let (Some(plan), Some(first)) = (plan_graph.as_ref(), deltas.first()) {
        if plan.nodes != first.before.nodes || plan.edges != first.before.edges {
            source_omission(
                &mut mutation_report,
                WorkGraphOmissionReason::ResolutionIncomplete,
                "mutation-log:first-before-does-not-match-plan",
            );
            mutation_report
                .omissions
                .last_mut()
                .expect("the mismatch omission was just appended")
                .detail = "the first observed mutation starts after the persisted plan state; an earlier structural change may be absent"
                .to_string();
        }
    }

    // Source reporting owns the legacy-plan omission in an archive. Passing an
    // explicit empty derivation base avoids counting the same absent file twice.
    let derivation_base = plan_graph.clone().unwrap_or_default();
    let (agent_principals, hierarchy_omission): (BTreeMap<String, String>, _) =
        match state.read_hierarchy() {
            Ok(hierarchy) => (
                hierarchy
                    .into_iter()
                    .filter_map(|node| node.principal.map(|principal| (node.id, principal)))
                    .collect(),
                None,
            ),
            Err(error) => {
                let mut omission = WorkGraphOmission::new(
                    WorkGraphOmissionReason::SourceUnreadable,
                    1,
                    vec!["state/hierarchy.json".to_string()],
                );
                omission.detail = format!(
                    "agent hierarchy could not be read; lane attribution may be incomplete: {error}"
                );
                (BTreeMap::new(), Some(omission))
            }
        };
    let mut derivation = derive_runtime_graph_with_completion_facts(
        Some(&derivation_base),
        &events,
        &journal,
        &ledger,
        &deltas,
        &completion_facts,
        &agent_principals,
    );
    let sources = vec![
        plan_report.clone(),
        event_report,
        journal_report,
        ledger_report,
        mutation_report,
    ];
    for report in &sources {
        for omission in &report.omissions {
            merge_omission(&mut derivation.runtime_graph, omission);
        }
    }
    if let Some(omission) = completion_ledger_omission.as_ref() {
        merge_omission(&mut derivation.runtime_graph, omission);
    }
    if let Some(omission) = hierarchy_omission.as_ref() {
        merge_omission(&mut derivation.runtime_graph, omission);
    }
    let divergence = compute_divergence(plan_graph.as_ref(), &derivation.runtime_graph, &deltas);
    let archive = WorkGraphArchive {
        schema_version: WORK_GRAPH_ARCHIVE_SCHEMA_VERSION,
        archive_id,
        session_id: session_id.to_string(),
        archived_at: Utc::now(),
        plan_graph,
        runtime_graph: derivation.runtime_graph,
        deltas,
        outcomes: derivation.outcomes,
        divergence,
        sources,
    };
    archive
        .reconstruct_structural_history()
        .map_err(ArchiveError::InvalidArchive)?;

    let mut temp = NamedTempFile::new_in(&archive_dir)?;
    serde_json::to_writer_pretty(&mut temp, &archive)?;
    let completion = match temp.persist_noclobber(&target) {
        Ok(_) => ArchiveCompletion {
            path: target,
            archive,
            created: true,
        },
        Err(_error) if target.exists() => ArchiveCompletion {
            archive: read_archive(&target)?,
            path: target,
            created: false,
        },
        Err(error) => return Err(ArchiveError::Io(error.error)),
    };
    StateManager::new(session_dir)
        .write_portable_work_graph_artifact(
            "archived",
            &completion.archive.runtime_graph,
            Some(&completion.archive.divergence),
        )
        .map_err(|error| ArchiveError::Storage(error.to_string()))?;
    Ok(completion)
}

pub fn launch_hive(
    &self,
    project_path: PathBuf,
    worker_count: u8,
    command: &str,
    prompt: Option<String>,
    name: Option<String>,
    color: Option<String>,
) -> Result<Session, String> {
    crate::instance::refuse("agent launch")?;
    let session_id = Uuid::new_v4().to_string();
    let mut agents = Vec::new();
    let prompt_str = prompt.unwrap_or_default();
    let cwd = project_path.to_str().unwrap_or(".");

    // Parse command without splitting quoted executable paths or arguments.
    let (launch_command, parsed_args) = Self::parse_legacy_launch_command(command)?;
    let cmd = launch_command.as_str();
    let base_args = parsed_args;
    let base_arg_refs: Vec<&str> = base_args.iter().map(String::as_str).collect();
    let launch_model = extract_model_arg(&base_arg_refs)
        .or_else(|| CliRegistry::default_model(cmd).map(ToString::to_string));

    {
        let pty_manager = self.pty_manager.read();

        // Create Queen agent
        let queen_id = format!("{}-queen", session_id);
        let mut queen_args = base_args.clone();
        if cmd == "claude" {
            Self::remove_claude_session_flags(&mut queen_args);
            queen_args.splice(0..0, ["--session-id".to_string(), Uuid::new_v4().to_string()]);
        }

        // Add prompt as positional argument if provided and command is claude
        if cmd == "claude" && !prompt_str.is_empty() {
            queen_args.push(prompt_str.clone());
        }

        tracing::info!(
            "Launching Queen agent: {} {:?} in {:?}",
            cmd,
            queen_args,
            project_path
        );

        let transcript_spawned_at = Some(Utc::now());
        pty_manager
            .create_session(
                queen_id.clone(),
                AgentRole::Queen,
                cmd,
                &queen_args.iter().map(String::as_str).collect::<Vec<_>>(),
                Some(cwd),
                120,
                30,
            )
            .map_err(|e| {
                let err_msg = format!("Failed to spawn Queen: {}", e);
                tracing::error!("{}", err_msg);
                err_msg
            })?;

        let queen_config = AgentConfig {
            cli: cmd.to_string(),
            model: launch_model.clone(),
            flags: base_args.iter().map(|s| s.to_string()).collect(),
            label: None,
            name: None,
            description: None,
            role: None,
            initial_prompt: None,
        };

        agents.push(AgentInfo {
            work_state: None,
            transcript_spawned_at,
            provider_session_id: None,
            transcript_session_id: Self::transcript_key(cmd, &queen_args),
            id: queen_id,
            role: AgentRole::Queen,
            status: AgentStatus::Running,
            config: queen_config,
            parent_id: None,
            role_definition_id: None,
            role_definition_version: None,
            commit_sha: None,
            base_commit_sha: None,
        });

        // Create Worker agents
        for i in 1..=worker_count {
            let worker_id = format!("{}-worker-{}", session_id, i);
            let mut worker_args = base_args.clone();
            if cmd == "claude" {
                Self::remove_claude_session_flags(&mut worker_args);
                worker_args.splice(0..0, ["--session-id".to_string(), Uuid::new_v4().to_string()]);
            }

            tracing::info!(
                "Launching Worker {} agent: {} {:?} in {:?}",
                i,
                cmd,
                worker_args,
                project_path
            );

            let transcript_spawned_at = Some(Utc::now());
            pty_manager
                .create_session(
                    worker_id.clone(),
                    AgentRole::Worker {
                        index: i,
                        parent: None,
                    },
                    cmd,
                    &worker_args.iter().map(String::as_str).collect::<Vec<_>>(),
                    Some(cwd),
                    120,
                    30,
                )
                .map_err(|e| {
                    let err_msg = format!("Failed to spawn Worker {}: {}", i, e);
                    tracing::error!("{}", err_msg);
                    err_msg
                })?;

            let worker_config = AgentConfig {
                cli: cmd.to_string(),
                model: launch_model.clone(),
                flags: base_args.iter().map(|s| s.to_string()).collect(),
                label: None,
                name: None,
                description: None,
                role: None,
                initial_prompt: None,
            };

            agents.push(AgentInfo {
                work_state: None,
                transcript_spawned_at,
                provider_session_id: None,
                transcript_session_id: Self::transcript_key(cmd, &worker_args),
                id: worker_id.clone(),
                role: AgentRole::Worker {
                    index: i,
                    parent: Some(format!("{}-queen", session_id)),
                },
                status: AgentStatus::Running,
                config: worker_config,
                parent_id: Some(format!("{}-queen", session_id)),
                role_definition_id: None,
                role_definition_version: None,
                commit_sha: None,
                base_commit_sha: None,
            });
        }
    }

    let (max_qa_iterations, qa_timeout_secs, auth_strategy) = default_session_qa_settings();
    let session = Session {
        id: session_id.clone(),
        name,
        color,
        session_type: SessionType::Hive { worker_count },
        project_path,
        state: SessionState::Running,
        created_at: Utc::now(),
        last_activity_at: Utc::now(),
        agents,
        default_cli: cmd.to_string(),
        default_model: launch_model,
        default_principal_cli: None,
        default_principal_model: None,
        default_principal_flags: Vec::new(),
        execution_policy: HiveExecutionPolicy::default(),
        qa_workers: Vec::new(),
        max_qa_iterations,
        qa_timeout_secs,
        qa_inconclusive_at: None,
        auth_strategy,
        worktree_path: None,
        worktree_branch: None,
        no_git: false,
        agent_resume_report: Vec::new(),
        resume_report: None,
    };

    {
        let mut sessions = self.sessions.write();
        sessions.insert(session_id.clone(), session.clone());
    }

    self.emit_agent_batch_launched(&session, &session.agents);

    if let Some(ref app_handle) = self.app_handle {
        let _ = app_handle.emit(
            "session-update",
            SessionUpdate {
                session: session.clone(),
            },
        );
    }

    self.init_session_storage(&session);
    Ok(session)
}

    fn build_queen_master_prompt(
        queen_config: &AgentConfig,
        project_path: &Path,
        queen_workspace_path: &Path,
        session_id: &str,
        workers: &[AgentConfig],
        user_prompt: Option<&str>,
        has_plan: bool,
        has_evaluator: bool,
        execution_policy: &HiveExecutionPolicy,
    ) -> String {
        let path_for_cli = |path: &Path| Self::prompt_path_for_cli(path, &queen_config.cli);
        let api_curl = Self::api_curl(&queen_config.cli);
        let role = ContractRole::Queen;
        let policy = &execution_policy.queen_delegation;
        let card = CliRegistry::infer_capabilities(&queen_config.cli);
        let delegation_authorized = CliRegistry::native_delegation_authorized(&card, policy);
        let role_kernel = render_role_kernel(role);
        let capability_card = render_capability_card(
            queen_config,
            role,
            &card,
            policy,
            &execution_policy.workspace_strategy,
            delegation_authorized,
            &execution_policy.tier_policy,
            Some(TaskTier::Critical),
        );
        let delegation = render_delegation_guidance(role, policy, delegation_authorized);
        let workspace_contract =
            render_workspace_contract(role, &execution_policy.workspace_strategy);

        let session_root = Self::session_prompt_root(project_path, session_id, &queen_config.cli);
        let plan_path = path_for_cli(&session_root.join("plan.md"));
        let tools_dir = path_for_cli(&session_root.join("tools"));
        let coordination_log_path = path_for_cli(&session_root.join("coordination.log"));
        let queen_workspace = path_for_cli(queen_workspace_path);
        let queen_conversation =
            path_for_cli(&session_root.join("conversations").join("queen.md"));
        let shared_conversation =
            path_for_cli(&session_root.join("conversations").join("shared.md"));

        let objective = user_prompt
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("Execute the approved plan or coordinate the configured objective.");
        let owned_scope = format!(
            "Orchestration artifacts, integration, validation, and git state for the managed session rooted at {}",
            queen_workspace
        );
        let deliverables = [
            "Clear, non-overlapping principal assignments",
            "One reconciled implementation with validation evidence",
            "Completed QA and external-review gates when configured",
        ];
        let validation = [
            "Every accepted workstream has evidence from its assigned principal",
            "Every accepted UI workstream includes its slop-check verdict path and mode, with unavailable explicitly recorded rather than treated as pass.",
            "Shared files and git operations were serialized",
            "The integrated result satisfies the plan and operator objective",
        ];
        let stop_conditions = [
            "The plan requires authority the operator did not grant",
            "A principal reports a blocker that changes scope or acceptance criteria",
            "QA or Prince returns BLOCKED",
        ];
        let assignment = render_assignment_contract(&AssignmentSpec {
            objective,
            access: "Coordinate managed principals, inspect all session workspaces, maintain session control artifacts, and perform integration operations",
            owned_scope: &owned_scope,
            authoritative_input: "The operator objective, approved plan, repository state, principal evidence, QA verdicts, and review findings",
            deliverables: &deliverables,
            validation: &validation,
            stop_conditions: &stop_conditions,
        });

        let plan_section = if has_plan {
            format!(
                "## Approved Plan\n\nRead {} before assigning work. Preserve its acceptance criteria and dependency order; adjust principal count only when coupling or capacity warrants it.",
                plan_path
            )
        } else {
            "## Planning Basis\n\nNo generated plan is present. Derive the smallest coherent workstream set from the operator objective and repository evidence.".to_string()
        };

        let principal_policy_label = match execution_policy.principal_delegation.mode {
            crate::domain::NativeDelegationMode::Disabled => "disabled",
            crate::domain::NativeDelegationMode::Auto => "auto",
            crate::domain::NativeDelegationMode::Encouraged => "encouraged",
        };
        let mut principal_roster = String::new();
        for (offset, principal) in workers.iter().enumerate() {
            let index = offset + 1;
            let principal_id = format!("{session_id}-worker-{index}");
            let label = principal
                .role
                .as_ref()
                .map(|worker_role| worker_role.label.as_str())
                .unwrap_or("Coding Principal");
            let model = principal.model.as_deref().unwrap_or("harness default");
            let flags =
                serde_json::to_string(&principal.flags).unwrap_or_else(|_| "[]".to_string());
            let principal_card = CliRegistry::infer_capabilities(&principal.cli);
            let support = match principal_card.native_delegation {
                crate::domain::CapabilitySupport::Supported => "supported",
                crate::domain::CapabilitySupport::Unsupported => "unsupported",
                crate::domain::CapabilitySupport::Unknown => "unknown",
            };
            let authorized = CliRegistry::native_delegation_authorized(
                &principal_card,
                &execution_policy.principal_delegation,
            );
            let principal_workspace = match execution_policy.workspace_strategy {
                WorkspaceStrategy::SharedCell => queen_workspace_path.to_path_buf(),
                WorkspaceStrategy::IsolatedCell => project_path
                    .join(".hive-manager")
                    .join("worktrees")
                    .join(session_id)
                    .join(format!("worker-{index}")),
                WorkspaceStrategy::None => project_path.to_path_buf(),
            };
            let principal_workspace = path_for_cli(&principal_workspace);
            let task_file = path_for_cli(
                &PathBuf::from(&principal_workspace)
                    .join(".hive-manager")
                    .join("tasks")
                    .join(format!("worker-{index}-task.md")),
            );
            principal_roster.push_str(&format!(
                "| {principal_id} | {label} | {cli} | {model} | {flags} | {support}; {principal_policy_label} ({authorization}) | {principal_workspace} | {task_file} |\n",
                cli = principal.cli,
                flags = flags,
                authorization = if authorized { "authorized" } else { "not authorized" },
            ));
        }
        if principal_roster.is_empty() {
            principal_roster.push_str("| None configured | - | - | - | - | - | - | - |\n");
        }

        let topology_instructions = match execution_policy.workspace_strategy {
            WorkspaceStrategy::SharedCell => format!(
                "## Shared Cell Integration\n\nThe Queen and managed principals run in the same backend-created worktree at {queen_workspace}. Assign explicit, non-overlapping paths and serialize shared files. Principal edits are immediately visible. Principals do not commit. Review the combined diff, run integration validation, then commit from the current backend-created hive/{session_id}/primary branch. Do not create, rename, or switch branches."
            ),
            WorkspaceStrategy::IsolatedCell => format!(
                "## Isolated Cell Integration\n\nThe Queen runs at {queen_workspace}. Each principal owns the workspace and task path in the roster and commits only its completed assignment on its backend-created hive/{session_id}/worker-N branch. Inspect and validate each commit, then integrate it into the current backend-created Queen branch in dependency order. Resolve conflicts centrally. Do not create, rename, or switch managed branches."
            ),
            WorkspaceStrategy::None => format!(
                "## Current Checkout Coordination\n\nAgents run in the operator checkout rooted at {queen_workspace}. Preserve operator changes. Do not create, switch, commit, or push branches without explicit operator authorization."
            ),
        };

        let required_protocol = Self::queen_required_protocol(&session_root, has_evaluator);
        let qa_milestone_handoff = if has_evaluator {
            Self::build_qa_milestone_handoff(session_id, &session_root, "managed principals", &queen_config.cli,)
        } else {
            String::new()
        };
        let post_workers_protocol = Self::queen_post_workers_protocol(
            session_id,
            &session_root,
            has_evaluator,
            Self::project_has_judge_tool(project_path),
            &queen_config.cli,
        );
        let queen_heartbeat = heartbeat_snippet_for_cli(
            &queen_config.cli,
            "http://localhost:18800",
            session_id,
            "queen",
            "working",
            "Coordinating managed principals",
            &[],
        );
        let queen_completed_heartbeat = heartbeat_snippet_for_cli(
            &queen_config.cli,
            "http://localhost:18800",
            session_id,
            "queen",
            "completed",
            "Objective and every configured gate complete",
            &[],
        );

        format!(
            r#"# Queen - Hive Meta-Harness

{role_kernel}

{capability_card}

{delegation}

{workspace_contract}

{assignment}

## Session

- Session ID: {session_id}
- Runtime CWD: {queen_workspace}
- Harness: {cli}
- Model: {model}
- Session tools: {tools_dir}
- Queen conversation: {queen_conversation}
- Shared conversation: {shared_conversation}

{required_protocol}

{plan_section}

## Managed Principal Roster

Managed principals are visible Hive agents with their own lifecycle and task contracts. Native children are private harness-managed lanes governed by the Capability Card; they are not substitutes for managed principals and must not create Hive Workers.

| ID | Role | Harness | Model | Flags (JSON) | Native delegation | Workspace | Task file |
|----|------|---------|-------|--------------|-------------------|-----------|-----------|
