fn validate_order(order: &mut Order, store: &mut Store, mailer: &Mailer) -> bool {
    if order.items.is_empty() {
        return false;
    }
    order.total = order.items.iter().map(|item| item.price).sum();
    store.orders.insert(order.id, order.clone());
    mailer.send(&order.customer_email, "Order received");
    true
}

fn is_expired(session: &mut Session, now: u64) -> bool {
    let expired = now > session.expires_at;
    if expired {
        session.token.clear();
        session.user_id = 0;
    }
    session.last_checked = now;
    expired
}

fn handle(a: &mut Vec<i64>, b: i64, mode: u8) -> i64 {
    if mode == 1 {
        a.push(b);
        return a.len() as i64;
    }
    if mode == 2 {
        a.retain(|v| *v != b);
        return 0;
    }
    a.iter().sum()
}

fn total_price(items: &[LineItem]) -> u64 {
